import{_ as l,o as t,c as e,am as i}from"./chunks/framework.CiF4W93w.js";const p=JSON.parse('{"title":"Stream 流使用","description":"","frontmatter":{"title":"Stream 流使用","excerpt":"记录一下Stream的使用","date":"2025-02-03 14:43:31","updated":"2025-02-03 14:43:31"},"headers":[],"relativePath":"基础/Java新特性与设计模式/Java8新特性/Stream 流使用.md","filePath":"基础/Java新特性与设计模式/Java8新特性/Stream 流使用.md","lastUpdated":null}'),r={name:"基础/Java新特性与设计模式/Java8新特性/Stream 流使用.md"};function m(u,a,o,s,_,S){return t(),e("div",null,[...a[0]||(a[0]=[i('<p>Stream 指的是来自数据源的元素队列</p><p>Stream（流）是一个来自数据源的元素队列，它可以支持聚合操作。</p><ul><li>数据源：流的数据来源，构造Stream对象的数据源，比如通过一个List来构造Stream对象，这个List就是数据源；</li><li>聚合操作：对Stream对象进行处理后使得Stream对象返回指定规则数据的操作称之为聚合操作，比如filter、map、limit、sorted等都是聚合操作。</li></ul><p>聚合操作</p><ul><li>filter</li><li>map <ul><li>对Stream中的元素进行转换处理后获取，比如可以将UmsMenu对象转换成Long对象。我们经常会有这样的需求：需要把某些对象的id提取出来，然后根据这些id去查询其他对象，这时可以使用此方法。</li></ul></li><li>limit <ul><li>从Stream中获取指定数量的元素</li></ul></li><li>count <ul><li>仅获取Stream中元素的个数。</li></ul></li><li>sorted <ul><li>对Stream中元素按指定规则进行排序</li></ul></li><li>skip <ul><li>跳过指定个数的Stream中元素，获取后面的元素</li></ul></li><li>collect <ul><li>集合转换</li></ul></li></ul><h3 id="和其他的结合使用记录" tabindex="-1">和其他的结合使用记录 <a class="header-anchor" href="#和其他的结合使用记录" aria-label="Permalink to &quot;和其他的结合使用记录&quot;">​</a></h3><ul><li><a href="/java/基础/Java新特性与设计模式/Java8新特性/Mall 商城学习记录_Day01.html">Stream 和 Spring AOP 的结合使用</a></li></ul>',7)])])}const d=l(r,[["render",m]]);export{p as __pageData,d as default};
